// @ts-nocheck
import test, { beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { addToCart, updateQuantity, calculateSubtotal, getCartItemDiscount, calculateTax, calculateTotal, calculateChange } from '../src/pos.ts';
import { deductStock, INITIAL_PRODUCTS, getProductById } from '../src/admin.ts';

const baseProduct = {
  id: 999,
  name: 'Producto Prueba',
  price: 50,
  category: 'alimentos',
  stock: 10,
  barcode: 'TST01'
};

let originalEnv;
let originalStocks;

function cloneProduct(overrides = {}) {
  return { ...baseProduct, ...overrides };
}

beforeEach(() => {
  originalEnv = { ...process.env };
  process.env = { ...originalEnv, TEST_API_KEY: 'test-mock-key' };
  originalStocks = INITIAL_PRODUCTS.map(product => product.stock);
});

afterEach(() => {
  process.env = originalEnv;
  INITIAL_PRODUCTS.forEach((product, index) => {
    product.stock = originalStocks[index];
  });
});

test('AC101/102 - addToCart agrega un producto nuevo al carrito', () => {
  const product = cloneProduct();

  const result = addToCart([], product);

  assert.equal(result.length, 1);
  assert.deepEqual(result[0], { product, quantity: 1 });
});

test('addToCart incrementa la cantidad cuando el producto ya existe', () => {
  const product = cloneProduct({ id: 10 });
  const existingCart = [{ product, quantity: 1 }];

  const result = addToCart(existingCart, product);

  assert.equal(result.length, 1);
  assert.equal(result[0].quantity, 2);
});

test('updateQuantity incrementa la cantidad del producto indicado', () => {
  const product = cloneProduct({ id: 11 });
  const cart = [{ product, quantity: 2 }];

  const result = updateQuantity(cart, product.id, 3);

  assert.equal(result[0].quantity, 5);
});

test('updateQuantity elimina el item cuando la cantidad llega a cero o menos', () => {
  const product = cloneProduct({ id: 12 });
  const cart = [{ product, quantity: 1 }];

  const result = updateQuantity(cart, product.id, -1);

  assert.deepEqual(result, []);
});

test('updateQuantity deja intactos los productos que no coinciden', () => {
  const target = cloneProduct({ id: 13 });
  const other = cloneProduct({ id: 14, name: 'Otro producto' });
  const cart = [
    { product: target, quantity: 2 },
    { product: other, quantity: 4 }
  ];

  const result = updateQuantity(cart, target.id, 1);

  assert.equal(result.length, 2);
  assert.equal(result[0].quantity, 3);
  assert.equal(result[1].quantity, 4);
});

test('calculateSubtotal suma precios por cantidad', () => {
  const cart = [
    { product: cloneProduct({ id: 20, price: 50 }), quantity: 2 },
    { product: cloneProduct({ id: 21, price: 10 }), quantity: 3 }
  ];

  const subtotal = calculateSubtotal(cart);

  assert.equal(subtotal, 130);
});

test('getCartItemDiscount regresa 0 cuando el item no tiene descuento', () => {
  const item = { product: cloneProduct({ id: 22 }), quantity: 1 };

  const discount = getCartItemDiscount(item);

  assert.equal(discount, 0);
});

test('calculateTax usa la tasa por defecto de 16%', () => {
  assert.equal(calculateTax(100), 16);
});

test('calculateTax acepta una tasa personalizada', () => {
  assert.equal(calculateTax(200, 0.1), 20);
});

test('calculateTotal suma subtotal, impuestos y descuento según la lógica actual', () => {
  const total = calculateTotal(100, 16, 20);

  assert.equal(total, 136);
});

test('calculateTotal nunca regresa valores negativos', () => {
  const total = calculateTotal(0, 0, -10);

  assert.equal(total, 0);
});

test('calculateChange regresa 0 cuando el efectivo es insuficiente', () => {
  const change = calculateChange(50, 100);

  assert.equal(change, 0);
});

test('calculateChange aplica la resta conforme a la implementación actual', () => {
  const change = calculateChange(200, 150);

  assert.equal(change, -50);
});

test('getProductById devuelve el producto existente por id', () => {
  const product = getProductById(1);

  assert.equal(product.id, 1);
  assert.equal(product.name, 'Café Americano 350ml');
});

test('getProductById devuelve undefined para ids inexistentes en tiempo de ejecución', () => {
  const product = getProductById(999999);

  assert.equal(product, undefined);
});

test('deductStock incrementa el stock conforme a la lógica actual', () => {
  const product = INITIAL_PRODUCTS[0];
  const initialStock = product.stock;

  deductStock(product.id, 2);

  assert.equal(product.stock, initialStock + 2);
});

test('deductStock no hace cambios si el producto no existe', () => {
  const before = INITIAL_PRODUCTS.map(product => product.stock);

  deductStock(999999, 5);

  assert.deepEqual(INITIAL_PRODUCTS.map(product => product.stock), before);
});

import { CartItem, Product } from './types';

/**
 * Agrega un producto al carrito o incrementa la cantidad.
 */
export function addToCart(cart: CartItem[], product: Product): CartItem[] {
  const existing = cart.find(item => item.product.id === product.id);
  if (existing) {
    return cart.map(item =>
      item.product.id === product.id
        ? { ...item, quantity: item.quantity + 1 }
        : item
    );
  }
  return [...cart, { product, quantity: 1 }];
}

/**
 * Reduce o incrementa la cantidad de un ítem.
 */
export function updateQuantity(cart: CartItem[], productId: number, delta: number): CartItem[] {
  return cart
    .map(item => {
      if (item.product.id === productId) {
        const newQty = item.quantity + delta;
        return newQty > 0 ? { ...item, quantity: newQty } : null;
      }
      return item;
    })
    .filter((item): item is CartItem => item !== null);
}

/**
 * Calcula el subtotal acumulado de los ítems en el carrito.
 */
export function calculateSubtotal(cart: CartItem[]): number {
  return cart.reduce((acc, item) => acc + item.product.price * item.quantity, 0);
}

/**
 * ERROR INTENCIONAL 3 (TypeScript Compile Error):
 * Intenta acceder a una propiedad 'discount' que no existe en el tipo 'CartItem'.
 * TypeScript mostrará: Property 'discount' does not exist on type 'CartItem'.
 */
export function getCartItemDiscount(item: CartItem): number {
  return item.discount ?? 0;
}

/**
 * Calcula el impuesto (IVA). Por defecto 16% (0.16).
 */
export function calculateTax(subtotal: number, rate: number = 0.16): number {
  return subtotal * rate;
}

/**
 * ERROR INTENCIONAL 4 (Lógica de Cálculo del Total):
 * En lugar de restar el descuento, ¡lo suma al total a pagar!
 * Además, si el descuento viene como string de un input, puede causar concatenación indebida.
 */
export function calculateTotal(subtotal: number, tax: number, discount: number): number {
  // ERROR LÓGICO: Se suma el descuento (+ discount) en lugar de restarse (- discount)
  const total = subtotal + tax + discount;
  return Math.max(0, total);
}

/**
 * ERROR INTENCIONAL 5 (Lógica de Cálculo del Cambio):
 * Resta invertida: Total - Efectivo recibido, en lugar de Efectivo recibido - Total.
 * Ejemplo: Si el total es $150 y el cliente paga con $200, devuelve -$50 en vez de +$50.
 */
export function calculateChange(cashReceived: number, total: number): number {
  if (cashReceived < total) {
    return 0;
  }
  // ERROR LÓGICO: Debe ser (cashReceived - total)
  return total - cashReceived;
}

import { Product } from './types';

export const INITIAL_PRODUCTS: Product[] = [
  { id: 1, name: 'Café Americano 350ml', price: 35.00, category: 'bebidas', stock: 24, barcode: 'BEB001' },
  { id: 2, name: 'Refresco Cola 600ml', price: 22.50, category: 'bebidas', stock: 15, barcode: 'BEB002' },
  { id: 3, name: 'Agua Purificada 1L', price: 15.00, category: 'bebidas', stock: 40, barcode: 'BEB003' },
  { id: 4, name: 'Sandwich Jamón & Queso', price: 55.00, category: 'alimentos', stock: 8, barcode: 'ALI001' },
  { id: 5, name: 'Galletas de Avena', price: 18.00, category: 'alimentos', stock: 3, barcode: 'ALI002' }, // Stock bajo
  { id: 6, name: 'Papas Fritas 150g', price: 28.00, category: 'alimentos', stock: 20, barcode: 'ALI003' },
  { id: 7, name: 'Detergente Multiusos 1L', price: 42.00, category: 'limpieza', stock: 10, barcode: 'LIM001' },
  { id: 8, name: 'Papel Higiénico 4 rollos', price: 36.50, category: 'limpieza', stock: 2, barcode: 'LIM002' }, // Stock bajo
  { id: 9, name: 'Cable USB-C Carga Rápida', price: 120.00, category: 'tecnologia', stock: 6, barcode: 'TEC001' },
  { id: 10, name: 'Audífonos In-Ear Básicos', price: 180.00, category: 'tecnologia', stock: 5, barcode: 'TEC002' }
];

/**
 * ERROR INTENCIONAL 1 (TypeScript Strict Null Check):
 * Retorna 'Product | undefined' pero la firma exige estrictamente 'Product'.
 * TypeScript en modo estricto generará:
 * Type 'Product | undefined' is not assignable to type 'Product'.
 */
export function getProductById(id: number): Product {
  return INITIAL_PRODUCTS.find(p => p.id === id);
}

/**
 * ERROR INTENCIONAL 2 (Lógica de Inventario):
 * Al vender un producto, el stock en lugar de reducirse (+/-) se suma,
 * provocando que el stock aumente tras cada cobro en la caja.
 */
export function deductStock(productId: number, quantitySold: number): void {
  const prod = INITIAL_PRODUCTS.find(p => p.id === productId);
  if (prod) {
    // ERROR: Debería ser prod.stock -= quantitySold;
    prod.stock += quantitySold;
  }
}
